'use strict';

// MODULES //

var setGlyph = require( './set-glyph.js' );

/**
* Method to draw the box frame.
*
* @private
* @name box_frame
* @returns {void}
*/
function boxFrame() {
	var r;
	var c;
	var i;

	r = this._plotArea.row;
	c = this._plotArea.col;

	for ( i = r; i <= r + this._height; i++ ) {
		setGlyph( i, c, 'vertical', false );
		setGlyph( i, c + this._width, 'vertical', false );
	}

	for ( i = c; i <= c + this._width; i++ ) {
		setGlyph( r, i, 'horizontel', false );
		setGlyph( r, i, 'horizontel', false );
	}

	// Corners
	setGlyph( r, c, 'LBcorner', true );
	setGlyph( r + this._height, c, 'LTcorner', true );
	setGlyph( r, c + this._width, 'RBcorner', true );
	setGlyph( r + this._height, c + this._width, 'RTcorner', true );
}

module.exports = boxFrame;
